import apiClient from './apiClient';

const SUBJECT_API = '/subjects';

const createSubject = async (subjectData) => {
  try {
    console.log('📤 subjectService: createSubject called with:', subjectData);
    const response = await apiClient.post(SUBJECT_API, subjectData);
    return response.data;
  } catch (error) {
    console.error('❌ subjectService: Error creating subject:', error);
    throw error;
  }
};

const getSubjectsByCourse = async (courseId) => {
  try {
    const response = await apiClient.get(`${SUBJECT_API}/${courseId}`);
    return response.data;
  } catch (error) {
    console.error('Error fetching subjects:', error);
    throw error;
  }
};

const updateSubject = async (subjectId, updates) => {
  try {
    const response = await apiClient.put(`${SUBJECT_API}/${subjectId}`, updates);
    return response.data;
  } catch (error) {
    console.error('Error updating subject:', error);
    throw error;
  }
};

const deleteSubject = async (subjectId) => {
  try {
    const response = await apiClient.delete(`${SUBJECT_API}/${subjectId}`);
    return response.data;
  } catch (error) {
    console.error('Error deleting subject:', error);
    throw error;
  }
};

export default {
  createSubject,
  getSubjectsByCourse,
  updateSubject,
  deleteSubject
};
